def slate_resolves(
        reel: Path, bid: str) -> bool:
    for rel in (
      f'media/{bid}.mp4',
      f'manim/{bid}.mp4',
      f'manim/{bid}.mov',
    ):
        if (reel/rel).exists():
            return False
    return True

def find_slates(reel: Path):
    """Beats needing FormACard fill."""
    sheet_path = reel / 'beat_sheet.json'
    if not sheet_path.exists():
        return [], None
    sheet = json.loads(sheet_path.read_text())
    slates = []
    for b in sheet.get('beats', []):
        bid = b.get('beat_id','')
        if not slate_resolves(reel, bid):
            continue  # already rendered
        if b.get('silent'):
            continue  # intentional silence
        if (b.get('shot',{}).get('remotion',{})
              .get('pattern')):
            continue  # already patterned
        slates.append(b)
    return slates, sheet
